#!/usr/bin/ruby
# MavericksResurrection standalone EFI diagnostics. Does not patch the app or OS.
require 'json'
require 'open3'
require 'digest'
require 'fileutils'
require 'tmpdir'
require 'etc'
require 'securerandom'
require 'base64'
require 'time'
require 'timeout'

module MRDiag
  VERSION = '1.0 Beta 5'
  MARKER = "MavericksResurrection EFI diagnostics v1\n"
  BASE = 'MavericksResurrection-Diagnostics'
  UUID = /\A[0-9A-F]{8}-[0-9A-F]{4}-[0-9A-F]{4}-[0-9A-F]{4}-[0-9A-F]{12}\z/i
  DEVICE = /\Adisk[0-9]+s[0-9]+\z/
  BOOT = 'System/Library/CoreServices/boot.efi'
  PAYLOADS = JSON.parse('{"MavericksDiagnostics.efi": {"bytes": 63488, "sha256": "a051c16c4c2c2607325a0a1b60789b490b1de318c103df0bf79b9fbb03fa4fc8", "base64": ""}}')

  def self.guid_bytes(text)
    raise 'Invalid GPT partition UUID.' unless text.to_s =~ UUID
    b = [text.delete('-')].pack('H*')
    b[0,4].reverse + b[4,2].reverse + b[6,2].reverse + b[8,8]
  end
  def self.safe_existing(root, relative, directory = false)
    raise 'Unsafe relative path.' if relative.start_with?('/') || relative.split('/').any? {|s| s.empty? || s == '.' || s == '..'}
    current = File.realpath(root)
    relative.split('/').each do |part|
      current = File.join(current, part)
      st = File.lstat(current)
      raise "Symbolic link refused: #{relative}" if st.symlink?
    end
    st = File.lstat(current)
    raise "Unexpected file type: #{relative}" unless directory ? st.directory? : st.file?
    current
  end
  def self.new_file(path, bytes)
    File.open(path, File::WRONLY | File::CREAT | File::EXCL, 0600) {|f| f.binmode; f.write(bytes); f.flush; f.fsync}
    raise "Write verification failed: #{File.basename(path)}" unless Digest::SHA256.file(path).hexdigest == Digest::SHA256.hexdigest(bytes)
  end

  class Session
    def initialize
      @user = Etc.getpwuid(Integer(ENV.fetch('SUDO_UID')))
      @desktop = File.realpath(File.join(@user.dir, 'Desktop'))
      @owned_mounts = []
      @temporary = Dir.mktmpdir('MavericksResurrection-EFI-', '/private/tmp')
      @commands = []
      @report = nil
      Dir.chdir('/')
    end
    def run(argv, input = nil, seconds = 60)
      output = ''.b
      result = nil
      Open3.popen2e(*argv, :pgroup => true) do |stdin, pipe, waiter|
        stdin.binmode; stdin.write(input) if input; stdin.close
        begin
          Timeout.timeout(seconds) do
            while (chunk = pipe.read(65536))
              output << chunk
              raise 'Command output limit reached.' if output.bytesize > 16 * 1024 * 1024
            end
            result = waiter.value.exitstatus
          end
        rescue Exception
          begin Process.kill('TERM', -waiter.pid); rescue Errno::ESRCH; end
          unless waiter.join(3)
            begin Process.kill('KILL', -waiter.pid); rescue Errno::ESRCH; end
          end
          raise
        end
      end
      @commands << {'argv'=>argv, 'exit'=>result}
      raise "#{File.basename(argv[0])} failed: #{output.force_encoding('UTF-8').scrub}" unless result == 0
      output
    end
    def plist(bytes)
      JSON.parse(run(['/usr/bin/plutil','-convert','json','-o','-','-'], bytes))
    end
    def info(device)
      plist(run(['/usr/sbin/diskutil','info','-plist',device]))
    end
    def inventory
      list = plist(run(['/usr/sbin/diskutil','list','-plist']))
      list.fetch('AllDisks').select {|d| d =~ DEVICE}.map do |device|
        begin info(device); rescue => e; puts "Cannot inspect #{device}: #{e.message}"; nil; end
      end.compact
    end
    def choose(list, prompt)
      raise 'No eligible partitions found.' if list.empty?
      puts "\n#{prompt}"
      list.each_with_index do |i,n|
        puts "#{n+1}) #{i['VolumeName'].to_s.inspect} | #{i['DeviceIdentifier']} | #{i['Internal'] ? 'internal' : 'external / image'} | #{(i['TotalSize'].to_f / 1073741824).round(2)} GiB | #{i['FilesystemName'] || i['Content']} | #{i['MountPoint'].to_s.empty? ? 'unmounted' : 'mounted'}"
      end
      print 'Number (Q cancels): '
      text = $stdin.gets.to_s.strip
      raise 'Cancelled.' if text.empty? || text =~ /\Aq\z/i
      raise 'Invalid selection.' unless text =~ /\A[1-9][0-9]*\z/ && text.to_i <= list.length
      list[text.to_i-1]
    end
    def recheck(old)
      fresh = info(old.fetch('DeviceIdentifier'))
      # TotalSize can switch between partition and FAT filesystem capacity on mount.
      # IOKitSize and the partition offset identify the underlying partition extent.
      raise 'Cannot establish the partition extent.' unless old['IOKitSize'].to_i>0 && old['PartitionMapPartitionOffset'].to_i>0
      %w[DeviceIdentifier DiskUUID VolumeUUID IOKitSize PartitionMapPartitionOffset WholeDisk Content FilesystemType].each do |key|
        raise "Partition identity changed (#{key}). Stop and prepare a new case." unless fresh[key] == old[key]
      end
      raise 'A GPT partition UUID is required.' unless fresh['DiskUUID'].to_s =~ UUID
      raise 'A whole disk cannot be selected.' unless fresh['WholeDisk'] == false && fresh['DeviceIdentifier'] =~ DEVICE
      fresh
    end
    def verify_mount(device, mount, readonly)
      prefix='/dev/'+device+' on '
      lines=run(['/sbin/mount']).lines.select {|line| line.start_with?(prefix)}
      expected=prefix+File.realpath(mount)+' ('
      raise 'Unexpected or duplicate mount for selected partition.' unless lines.length==1 && lines[0].start_with?(expected)
      ro=!!(lines[0] =~ /(?:\(|, )read-only(?:,|\))/)
      raise 'The mount is not read-only.' if readonly && !ro
      raise 'The mount is not writable.' if !readonly && ro
    end
    def readonly_target(chosen)
      fresh = recheck(chosen)
      raise 'An encrypted or locked volume cannot be used.' if fresh['Encrypted'] || fresh['Locked']
      raise 'The running macOS cannot be selected.' if ['/', '/System/Volumes/Data'].include?(fresh['MountPoint'])
      [@desktop, File.realpath(__FILE__)].each do |path|
        backing = run(['/bin/df','-P',path]).lines.last.to_s.split.first
        raise 'Keep this command and Desktop on your working macOS.' if backing == '/dev/'+fresh['DeviceIdentifier']
      end
      unless fresh['MountPoint'].to_s.empty?
        puts 'Unmounting the selected Mavericks partition normally. This may flush writes macOS already has pending.'
        run(['/usr/sbin/diskutil','unmount','/dev/'+fresh['DeviceIdentifier']])
      end
      fresh = recheck(chosen)
      raise 'The target is still mounted. Close applications using it and retry.' unless fresh['MountPoint'].to_s.empty?
      mount = File.join(@temporary,'Mavericks-readonly')
      Dir.mkdir(mount,0700)
      run(['/sbin/mount_hfs','-o','rdonly,noexec,nosuid,nodev,nobrowse','/dev/'+fresh['DeviceIdentifier'],mount])
      @owned_mounts << mount
      recheck(chosen)
      verify_mount(fresh['DeviceIdentifier'],mount,true)
      version = plist(File.binread(MRDiag.safe_existing(mount,'System/Library/CoreServices/SystemVersion.plist')))
      raise 'The selected partition does not contain Mavericks 10.9.' unless version['ProductVersion'].to_s =~ /\A10\.9(?:\.|\z)/
      boot = MRDiag.safe_existing(mount, BOOT)
      raise 'Unexpected boot.efi size.' unless File.size(boot).between?(1,16*1024*1024)
      result = {'partition'=>chosen, 'system_version'=>version, 'boot_efi_bytes'=>File.size(boot), 'boot_efi_sha256'=>Digest::SHA256.file(boot).hexdigest}
      run(['/sbin/umount',mount]); @owned_mounts.delete(mount)
      result
    end
    def fat_mount(chosen, readonly)
      fresh = recheck(chosen)
      raise 'Select a FAT EFI system partition, not a whole disk.' unless fresh['FilesystemType'] == 'msdos' && fresh['Content']=='EFI'
      unless fresh['MountPoint'].to_s.empty?
        verify_mount(fresh['DeviceIdentifier'],fresh['MountPoint'],false) unless readonly
        return File.realpath(fresh['MountPoint'])
      end
      mount = File.join(@temporary,'EFI-'+SecureRandom.hex(4))
      Dir.mkdir(mount,0700)
      options = 'noexec,nosuid,nodev'
      options = 'rdonly,'+options if readonly
      run(['/sbin/mount_msdos','-o',options,'/dev/'+fresh['DeviceIdentifier'],mount])
      @owned_mounts << mount
      recheck(chosen)
      verify_mount(fresh['DeviceIdentifier'],mount,readonly)
      mount
    end
    def dir(root,name)
      path=File.join(root,name)
      begin
        MRDiag.safe_existing(root,name,true)
      rescue Errno::ENOENT
        Dir.mkdir(path,0700)
      end
      MRDiag.safe_existing(root,name,true)
    end
    def host
      {'model'=>run(['/usr/sbin/sysctl','-n','hw.model']).strip, 'macos'=>run(['/usr/bin/sw_vers']).strip}
    end
    def desktop_report(prefix)
      @report=Dir.mktmpdir(prefix+'-'+Time.now.utc.strftime('%Y%m%dT%H%M%SZ')+'-',@desktop)
    end
    def prepare
      puts <<-TEXT
This prepares one EFI diagnostic tool with two modes. It does not change Mavericks,
OpenCore, boot order or existing EFI boot files. New files go in their own folder.
The selected Mavericks volume is accessed read-only and left unmounted.
Launching the boot-test EFI later is a real boot attempt: macOS can write to its disks.
Do not boot a damaged installation merely to collect a hardware report.
      TEXT
      all=inventory
      candidates=all.select {|i| i['FilesystemType']=='hfs' && !['/','/System/Volumes/Data'].include?(i['MountPoint']) && !i['WholeDisk']}
      target=choose(candidates,'Select the Mavericks installation to identify for this case:')
      result=readonly_target(target)
      fat=choose(all.select {|i| i['FilesystemType']=='msdos' && i['Content']=='EFI' && !i['WholeDisk']},'Select the EFI/FAT partition where the tools and their logs will be stored:')
      puts "\nNew diagnostics will be placed on #{fat['DeviceIdentifier']} (#{fat['VolumeName'].inspect}). Existing files are preserved."
      print 'Continue? [y/N]: '
      raise 'Cancelled before writing EFI files.' unless $stdin.gets.to_s.strip =~ /\Ay\z/i
      mount=fat_mount(fat,false)
      recheck(fat)
      base=dir(dir(mount,'EFI'),BASE)
      name='case-'+Time.now.utc.strftime('%Y%m%dT%H%M%SZ')+'-'+SecureRandom.hex(4)
      casepath=File.join(base,name);Dir.mkdir(casepath,0700)
      desktop_report('MavericksResurrection-EFI-Case')
      id={'tool'=>'MavericksResurrection EFI diagnostics','version'=>VERSION,'case'=>name,'created_utc'=>Time.now.utc.iso8601,'host'=>host,'target'=>result,'log_partition'=>fat,'efi_directory'=>'\\EFI\\'+BASE+'\\'+name}
      MRDiag.new_file(File.join(casepath,'case.json'),JSON.pretty_generate(id))
      MRDiag.new_file(File.join(@report,'case.json'),JSON.pretty_generate(id))
      PAYLOADS.each do |filename,record|
        raise 'Unexpected payload name.' unless ['MavericksDiagnostics.efi'].include?(filename)
        payload=Base64.strict_decode64(record.fetch('base64'))
        raise 'Embedded EFI integrity failure.' unless Digest::SHA256.hexdigest(payload)==record.fetch('sha256') && payload.bytesize==record.fetch('bytes')
        MRDiag.new_file(File.join(casepath,filename),payload)
      end
      raise 'The combined EFI payload is required.' unless PAYLOADS.keys.sort==['MavericksDiagnostics.efi']
      cfg='MRDIAG01'.b+MRDiag.guid_bytes(target.fetch('DiskUUID'))+[result.fetch('boot_efi_sha256')].pack('H*')+[result.fetch('boot_efi_bytes')].pack('Q<')
      MRDiag.new_file(File.join(casepath,'target.bin'),cfg)
      MRDiag.new_file(File.join(casepath,'ALLOW-DIAGNOSTICS.txt'),MARKER) # Only enable once everything is verified.
      instructions=usage(id)
      MRDiag.new_file(File.join(@report,'READ-ME-FIRST.txt'),instructions)
      MRDiag.new_file(File.join(casepath,'READ-ME-FIRST.txt'),instructions)
      puts instructions
      puts "\nPreparation finished. Instructions saved in: #{@report}"
      puts 'No boot has been attempted. Return to Debug and choose Collect EFI reports to make the report ZIP.'
    end
    def usage(id)
      efi=id.fetch('efi_directory');target=id.fetch('target').fetch('partition')
      <<-TEXT
MavericksResurrection EFI diagnostics #{VERSION}

Case: #{id['case']}
Mavericks target: #{target['VolumeName']} | #{target['DeviceIdentifier']} | #{target['Internal'] ? 'internal drive' : 'external drive (keep it connected)'}
Target GPT UUID: #{target['DiskUUID']}
Target volume UUID: #{target['VolumeUUID']}
EFI containing this tool AND all its logs: #{id['log_partition']['DeviceIdentifier']} | #{id['log_partition']['Internal'] ? 'internal drive' : 'external drive (keep it connected)'}
EFI partition GPT UUID: #{id['log_partition']['DiskUUID']}
Tool folder: #{efi}

1. OpenCore EFI and OpenShell are required. Use your existing OpenCore if you
   already have it. Otherwise install OpenCore EFI separately using OpenCore
   Legacy Patcher (OCLP), even if your current macOS does not require OpenCore.
   MavericksResurrection does not install or configure OpenCore or OpenShell.
   OCLP instructions: https://dortania.github.io/OpenCore-Legacy-Patcher/BUILD.html
   OpenCore here is a test environment, not a claim of official OCLP support for Mavericks.
2. Restart into your OpenCore EFI and choose OpenShell. Press Space in the picker
   if auxiliary entries are hidden. If OpenShell is not configured, refer to your
   OCLP/OpenCore documentation before continuing. Do not replace existing EFI files.
3. In OpenShell run: map -r
   Find the fsN: mapping with the EFI partition GPT UUID shown above.
   Check it using: dir fsN:#{efi}
   Replace fsN with the actual mapping, such as fs2. Do not assume fs0.
   The tool's EFI may be on a DIFFERENT disk from Mavericks: use the EFI UUID,
   not the Mavericks partition UUID, to find the tool's path.
4. Run: fsN:#{efi}\\MavericksDiagnostics.efi
   1 = Collect diagnostics only, then return to OpenShell.
   2 = Collect the same diagnostics, verify the selected Mavericks loader,
       then ask Y/N before trying to boot it.
   3 or Escape = Exit without collecting or booting.
   Logs always stay on this EFI partition in a new case subfolder. There is no
   fallback to another disk. If that EFI cannot be written, the test stops.
5. A boot attempt can write to Mavericks and other disks. Preserve a damaged
   installation before trying to boot it. Diagnostics-only does not boot or repair.
   The boot mode saves firmware and loader checkpoints, NOT the entire Mavericks
   kernel console after handoff. Photograph the last screen if startup stops.
   A before-startimage checkpoint does not prove Mavericks booted successfully.
6. Return to your working macOS, open MavericksResurrection > Debug > Collect EFI
   reports, and select the same EFI and case. Send the Desktop ZIP with your boot
   observations and photographs. Reports contain hardware identifiers and paths;
   review them before sharing. Nothing is uploaded automatically.

Disconnect HDMI from the laptop before booting Mavericks. If startup fails with
dock HDMI, disconnect it too. Record what was connected and whether NVMe support
was installed. For comparisons, use the same test version and OpenCore route.
OpenCore may change the firmware environment; this report records that environment.

If TargetNotExposedByFirmware appears, the firmware filesystem protocols did not
expose that GPT partition. No other installation is tried. If boot.efi changed or
the partition was reformatted, prepare a new case. Keep the read-only filesystem
report too: EFI diagnostics cannot establish the cause of filesystem corruption.
      TEXT
    end
    def collect
      fat=choose(inventory.select {|i| i['FilesystemType']=='msdos' && i['Content']=='EFI' && !i['WholeDisk']},'Select the EFI/FAT partition used for the test:')
      mount=fat_mount(fat,true)
      base=MRDiag.safe_existing(mount,'EFI/'+BASE,true)
      names=Dir.entries(base).select {|n| n =~ /\Acase-[A-Za-z0-9-]+\z/}.sort
      cases=names.select do |n|
        begin
          cp=MRDiag.safe_existing(base,n,true)
          marker=MRDiag.safe_existing(cp,'ALLOW-DIAGNOSTICS.txt')
          File.size(marker)==MARKER.bytesize && File.binread(marker)==MARKER
        rescue; false; end
      end
      raise 'No prepared cases found on this partition.' if cases.empty?
      puts "\nSelect the case:"
      cases.each_with_index {|n,i| puts "#{i+1}) #{n}"}
      print 'Number (Q cancels): ';answer=$stdin.gets.to_s.strip
      raise 'Cancelled.' unless answer =~ /\A[1-9][0-9]*\z/ && answer.to_i<=cases.length
      casepath=MRDiag.safe_existing(base,cases[answer.to_i-1],true)
      desktop_report('MavericksResurrection-EFI-Report')
      @count=0;@total=0;@hashes=[]
      copy_case(casepath,@report,'',0)
      print 'Boot route used (for example OpenCore -> OpenShell): ';route=$stdin.gets.to_s.strip
      print 'Did Mavericks reach the desktop? Describe the last visible screen: ';outcome=$stdin.gets.to_s.strip
      print 'HDMI/dock connections and anything else relevant: ';connections=$stdin.gets.to_s.strip
      print 'Was experimental NVMe support installed on this Mavericks target? ';nvme=$stdin.gets.to_s.strip
      observed={'collected_utc'=>Time.now.utc.iso8601,'host'=>host,'boot_route'=>route,'outcome'=>outcome,'connections'=>connections,'nvme_support'=>nvme,'files'=>@hashes,'commands'=>@commands}
      MRDiag.new_file(File.join(@report,'Collection.json'),JSON.pretty_generate(observed))
      zip=@report+'.zip'
      raise 'Report ZIP already exists.' if File.exist?(zip)
      run(['/usr/bin/ditto','-c','-k','--keepParent',@report,zip],nil,300)
      File.chown(@user.uid,@user.gid,zip)
      puts "\nSend this ZIP: #{zip}"
      puts 'Keep your screenshots and boot observations with it. No EFI or Mavericks files were changed by collection.'
    end
    def copy_case(src,dst,relative,depth)
      raise 'Report nesting limit reached.' if depth>4
      Dir.entries(src).sort.each do |name|
        next if ['.','..'].include?(name)
        raise 'Unexpected filename in diagnostics folder.' unless name =~ /\A[A-Za-z0-9_.-]+\z/
        path=File.join(src,name);st=File.lstat(path)
        raise 'A report contains a symbolic link or special file.' unless st.file? || st.directory?
        rel=relative.empty? ? name : relative+'/'+name
        if st.directory?
          raise 'Unexpected report directory.' unless depth==0 && name =~ /\A(?:hardware|boot|boot-return)-[0-9]{3}\z/i
          output=File.join(dst,name);Dir.mkdir(output,0700);copy_case(path,output,rel,depth+1)
        else
          next if name.downcase.end_with?('.efi') # Embedded tools need not be sent back.
          @count+=1;@total+=st.size
          raise 'Report size/file limit reached.' if @count>4096 || @total>256*1024*1024 || st.size>16*1024*1024
          data=File.binread(path)
          raise 'Report changed during collection.' if data.bytesize!=st.size
          MRDiag.new_file(File.join(dst,name),data)
          @hashes << {'path'=>rel,'bytes'=>data.bytesize,'sha256'=>Digest::SHA256.hexdigest(data)}
        end
      end
    end
    def cleanup
      @owned_mounts.reverse_each do |mount|
        begin run(['/sbin/umount',mount]); rescue => e; warn "Could not unmount #{mount}: #{e.message}"; end
      end
      if @report
        FileUtils.chown_R(@user.uid,@user.gid,@report)
      end
      # Remove only empty temporary mount directories; never recurse into a mount.
      Dir.entries(@temporary).each do |n|
        next if ['.','..'].include?(n)
        begin Dir.rmdir(File.join(@temporary,n)); rescue SystemCallError; end
      end
      begin Dir.rmdir(@temporary); rescue SystemCallError; end
    end
  end

end
